fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Since the problem guarantees that cafe appears in cafes,
    // we find the greatest index where cafes[i] == cafe.
    // Iterate from the end for efficiency.
    for i in (0..cafes.len()).rev() {
        if cafes[i] == cafe {
            return i;
        }
    }
    // Unreachable if cafe appears in cafes, but Rust requires a return.
    // If not found, return 0 as fallback.
    0
}

fn solve(cafes: Vec<i8>) -> i8 {
    // We want to find the value whose last occurrence position is minimal.
    // That means the value that last appears earliest in the array.
    // Strategy:
    // - Track last occurrence index for each distinct value.
    // - Then find the value with the smallest last occurrence index.

    use std::collections::HashMap;

    let mut last_occurrences: HashMap<i8, usize> = HashMap::new();

    // Record last occurrence for each value
    for (i, &cafe) in cafes.iter().enumerate() {
        last_occurrences.insert(cafe, i);
    }

    // Find the value with minimal last occurrence position
    // Since ties cannot occur because index is unique per occurrence,
    // just find min based on last occurrence index.
    let (&value_with_min_last_occurrence, _) = last_occurrences
        .iter()
        .min_by_key(|&(_, &pos)| pos)
        .expect("cafes is non-empty so there must be at least one element");

    value_with_min_last_occurrence
}